<?php $id=(int)($_GET['id']??0);$p=q('SELECT * FROM productos WHERE id=? AND activo=1',[$id])->fetch(); if(!$p): ?><div class="container py-5"><h2>Producto no encontrado</h2><a href="index.php?page=catalogo">Volver al catálogo</a></div><?php else: ?><div class="container py-5"><a href="index.php?page=catalogo" class="text-decoration-none text-dark">← Volver al catálogo</a><div class="row g-5 align-items-center mt-1"><div class="col-lg-6"><img class="img-fluid rounded-4 w-100" src="<?=h(product_image($p))?>" alt="<?=h($p['nombre'])?>"></div><div class="col-lg-6"><div class="kicker mb-3"><?=h($p['categoria'])?></div><h1 style="font-size:clamp(2rem,4vw,4rem)"><?=h($p['nombre'])?></h1><p class="lead mt-3"><?=h($p['descripcion'])?></p><dl class="row mt-4"><dt class="col-sm-4">Fabricante</dt><dd class="col-sm-8"><?=h($p['fabricante'])?></dd><dt class="col-sm-4">Origen</dt><dd class="col-sm-8"><?=h($p['origen'])?></dd><dt class="col-sm-4">Almacén</dt><dd class="col-sm-8"><?=(int)$p['cantidad_almacen']?> unidades</dd></dl><h3 class="mb-4"><?=money($p['precio'])?></h3><form method="post" action="actions.php" class="d-flex flex-wrap gap-2 align-items-center"><input type="hidden" name="action" value="add_cart"><?=csrf_input()?><input type="hidden" name="producto_id" value="<?=(int)$p['id']?>"><label for="qty">Cantidad</label><input class="form-control quantity-control" type="number" id="qty" name="cantidad" min="1" max="<?=max(1,(int)$p['cantidad_almacen'])?>" value="1"><button class="btn btn-brand" <?=$p['cantidad_almacen']<1?'disabled':''?>>Agregar al carrito →</button></form><div class="notice-box small mt-4">Producto de demostración académica. Verifica etiquetas, alérgenos y certificaciones reales antes de comercializar.</div></div></div></div><?php endif ?>
